import {loadSiteEditor,siteEditorScreen,bindSiteEditor,resetSiteEditor} from './site-editor.js';
import {copyHTML,copyRaw} from './site-copy.js';
import {loadSamples,samplesScreen,bindSamples,resetSampleEditor} from './sample-editor.js';
import {brandName,brandHTML} from './brand-state.js';
import {loadBranding} from './branding.js';
import {brandingScreen,bindBranding,clearBrandingPreview} from './branding-admin.js';
import {downloadSettingsScreen,loadDownloadSettings,bindDownloadSettings,resetDownloadSettings} from './download-settings.js';
import {watermarkEditor,bindWatermarkEditor,readWatermark} from './watermark-controls.js';
import {resetUsers,usersScreen,mailScreen,bindUsers,usersClick,loadUsersTab} from './users.js';
import {backend} from './backend.js';
import {loadStats,statsCards} from './analytics.js';
import {loadAbout,aboutEditor,bindAboutEditor} from './about.js';
import {escape as e} from './store.js';
import {subjectCatalog,subjectsScreen,bindSubjects,removeSubject} from './subjects.js';
const types={get "materials"(){return copyRaw("admin.fd10a146e962");},get "lectures"(){return copyRaw("admin.95f7caf5f942");},get "lectureNotes"(){return copyRaw("admin.b2b5202e7477");},get "cases"(){return copyRaw("admin.9ab92306f737");},get "flashcards"(){return copyRaw("admin.eac4b70868b6");},get "quizSets"(){return copyRaw("admin.dd0acd7417ae");},get "quizQuestions"(){return copyRaw("admin.f5f777044b10");}};
let state={status:'idle',items:{},type:'materials',query:'',error:''},busy=false;
let ui;
export function initAdmin(callbacks){ui=callbacks;}
let loadEpoch=0;
export function resetAdmin(){loadEpoch++;resetDownloadSettings();resetSampleEditor();resetSiteEditor();clearBrandingPreview();state={status:'idle',items:{},type:'materials',query:'',error:''};resetUsers();}
export async function loadAdmin(){const epoch=++loadEpoch,owner=backend.user()?.id;state.status='loading';state.error='';ui.render();try{await backend.refreshSession();if(!backend.user()){state.status='signedout';return;}if(!await backend.isAdmin()){state.status='denied';return;}await subjectCatalog.load();await loadAbout();await loadStats();await loadBranding();await loadSiteEditor();const results=await Promise.all(Object.keys(types).map(async type=>[type,await backend.cloudRead(type)]));if(epoch!==loadEpoch||backend.user()?.id!==owner)return;state.items=Object.fromEntries(results);state.status='ready';await loadUsersTab(state.type,ui);if(state.type==='downloadSettings')await loadDownloadSettings(ui);if(state.type==='samples')await loadSamples(ui);}catch(err){if(epoch!==loadEpoch)return;state.status='error';state.error=err.message;}finally{ui.render();}}
export function renderAdmin(){const heading=`<div class="heading"><div><span class="eyebrow">${brandHTML(true)} ${copyHTML("admin.bbdbcbf7345b")}</span><h1>${copyHTML("admin.a1ea4ff68e33")}</h1><p>${copyHTML("admin.6d30c2d72e35")}</p></div><button class="btn" id="admin-refresh">${copyHTML("admin.0e9161011702")}</button></div>`;
if(state.status==='idle'||state.status==='loading')return heading+`<div class="empty"><h3>${copyHTML("admin.2f0885e205d8")}</h3><p>${copyHTML("admin.1411a201077f")}</p></div>`;
if(state.status!=='ready'){const messages={signedout:['Sign in to manage shared content.','Use your username and password on the Log In page, then return here.'],denied:['Administrator access required.','Your account has not been added to lexamah_admins. Follow the setup guide to grant your own account access.'],error:['The admin dashboard needs setup.',state.error+' Run supabase/setup.sql in your Supabase SQL Editor, then refresh.']};const [title,description]=messages[state.status];return heading+`<div class="empty"><h3>${title}</h3><p>${e(description)}</p><button class="btn primary" data-route="login">${copyHTML("admin.fea8850128d0")}</button></div>`;}
const metrics=statsCards();const tabs=`<div class="admin-tabs">${Object.entries({...types,subjects:'Subjects',about:`About ${brandName()}`,users:'Users',mail:'Bulk Email',downloadSettings:'Download Settings',branding:'Branding Settings',samples:'Samples & Existing Content',siteEditor:'Text & Appearance'}).map(([key,label])=>`<button class="btn ${state.type===key?'primary':''}" data-admin-type="${key}">${key==='about'?`About ${brandHTML()}`:e(label)}</button>`).join('')}</div>`;if(state.type==='siteEditor')return heading+metrics+tabs+siteEditorScreen();if(state.type==='samples')return heading+metrics+tabs+samplesScreen();if(state.type==='branding')return heading+metrics+tabs+brandingScreen();if(state.type==='downloadSettings')return heading+metrics+tabs+downloadSettingsScreen();if(state.type==='users')return heading+metrics+tabs+usersScreen();if(state.type==='mail')return heading+metrics+tabs+mailScreen();if(state.type==='subjects')return heading+metrics+tabs+subjectsScreen();if(state.type==='about')return heading+metrics+tabs+aboutEditor();
const items=state.items[state.type]||[],filtered=items.filter(x=>`${x.title||x.name||x.front||x.question} ${x.subject||''}`.toLowerCase().includes(state.query.toLowerCase()));
return heading+metrics+`<div class="notice">${copyHTML("admin.b06f7e8860f6")}</div><div class="stats">${[['materials',copyRaw("admin.fd10a146e962")],['lectures',copyRaw("admin.95f7caf5f942")],['quizSets',copyRaw("admin.dd0acd7417ae")],['quizQuestions',copyRaw("admin.9a72221a2747")]].map(([k,v])=>`<div class="stat"><div><small>${v}</small><strong>${state.items[k]?.length||0}</strong><span class="sub">${copyHTML("admin.8685a2f15510")}</span></div></div>`).join('')}</div><div class="admin-tabs">${Object.entries({...types,subjects:'Subjects',about:`About ${brandName()}`,users:'Users',mail:'Bulk Email',downloadSettings:'Download Settings',branding:'Branding Settings',samples:'Samples & Existing Content',siteEditor:'Text & Appearance'}).map(([k,v])=>`<button class="btn ${state.type===k?'primary':''}" data-admin-type="${k}">${k==='about'?`About ${brandHTML()}`:e(v)}</button>`).join('')}</div><div class="toolbar"><input id="admin-search" aria-label="${copyHTML("admin.c0d59ffbd9b4")}" placeholder="Search ${types[state.type].toLowerCase()}…" value="${e(state.query)}"><button class="btn primary" id="admin-create">${copyHTML("admin.c007258c23b0")} ${types[state.type].toLowerCase()}</button></div><section class="card"><div class="card-head"><h2>${types[state.type]}</h2><span class="pill">${filtered.length} ${copyHTML("admin.a94e7bcfcbed")}</span></div>${filtered.length?filtered.map(x=>`<div class="row"><div class="row-copy"><strong>${e(x.title||x.name||x.front||x.question)}</strong><small>${e(x.subject||'Quiz question')}${x.file_name?` · ${e(x.file_name)}`:''}</small></div><button class="btn" data-admin-edit="${e(x.id)}">${copyHTML("admin.464c4ffd019e")}</button><button class="btn danger" data-admin-delete="${e(x.id)}">${copyHTML("admin.e2d0a54968ea")}</button></div>`).join(''):`<p class="muted">${copyHTML("admin.2da748b20572")}</p>`}</section><p class="muted">${copyHTML("admin.74a461348401")} <button class="text-button" data-route="studio">${copyHTML("admin.0d477a44f5cb")}</button>.</p>`;}
function field(name,label,value='',kind='input',attrs=''){return `<label for="admin-${name}">${label}</label><${kind} id="admin-${name}" name="${name}" ${kind==='input'?`value="${e(value)}"`:''} ${attrs}>${kind==='textarea'?e(value)+'</textarea>':''}`;}
function edit(id){if(state.status!=='ready')return;const type=state.type,x=id?state.items[type].find(x=>x.id===id):{};if(!x)return;if(type!=='quizQuestions'&&!subjectCatalog.options(x.subject).length){ui.toast(copyRaw("admin.93a995208be2"));return;}let html='';if(type==='flashcards')html=field('front',copyRaw("admin.289aff12b042"),x.front,'textarea','required maxlength="4000"')+field('back',copyRaw("admin.b2a3aa602762"),x.back,'textarea','required maxlength="10000"');else if(type==='quizQuestions'){if(!state.items.quizSets.length){ui.toast(copyRaw("admin.49cdde0b7884"));return;}html=`<label for="admin-quiz-set">${copyHTML("admin.e1bf4b3f3d18")}</label><select id="admin-quiz-set" name="quiz_set_id" required>${state.items.quizSets.map(q=>`<option value="${e(q.id)}" ${x.quiz_set_id===q.id?'selected':''}>${e(q.name)}</option>`).join('')}</select>`+field('question',copyRaw("admin.289aff12b042"),x.question,'textarea','required maxlength="4000"')+[0,1,2,3].map(i=>field(`option${i}`,`Option ${'ABCD'[i]}`,x.options?.[i]||'','input','required maxlength="2000"')).join('')+`<label for="admin-correct-index">${copyHTML("admin.fb019d338b43")}</label><select id="admin-correct-index" name="correct_index">${[0,1,2,3].map(i=>`<option value="${i}" ${Number(x.correct_index)===i?'selected':''}>${'ABCD'[i]}</option>`).join('')}</select>`+field('explanation',copyRaw("admin.16ee4625bce9"),x.explanation,'textarea','required maxlength="10000"');}else html=field(type==='quizSets'?'name':'title',copyRaw("admin.7e8cd2056da7"),x.name||x.title,'input','required maxlength="180"')+field('description',copyRaw("admin.526e0087cc3f"),x.description,'textarea','maxlength="4000"');if(type!=='quizQuestions')html+=`<label for="admin-subject">${copyHTML("admin.68971283841a")}</label><select id="admin-subject" name="subject">${subjectCatalog.options(x.subject).map(s=>`<option value="${e(s)}" ${s===x.subject?'selected':''}>${e(s)}${s===x.subject&&!subjectCatalog.names().includes(s)?' (no longer listed)':''}</option>`).join('')}</select>`;if(['materials','lectureNotes','cases'].includes(type))html+=field('body',type==='cases'?copyRaw("admin.e9987ce19e1d"):copyRaw("admin.0a6a90f5a4ec"),x.body,'textarea','maxlength="100000"');if(type==='cases')html+=field('citation',copyRaw("admin.a2a15fd54244"),x.citation);if(['materials','lectureNotes','cases','lectures'].includes(type)){if(type!=='lectures')html+=field('url',copyRaw("admin.9ffb7fed1806"),x.url,'input','type="url"');const audio=type==='lectures',watermarked=['materials','lectureNotes'].includes(type);html+=`<label for="admin-upload">${x.storage_path?copyRaw("admin.bebe38e427a4"):audio?copyRaw("admin.2f17498989c9"):copyRaw("admin.507ae671a6e1")}${audio?'':' (optional)'}</label><input id="admin-upload" name="upload" type="file" accept="${audio?'.mp3,.m4a,.aac,.wav,.ogg,.webm,.flac':watermarked?'.pdf,.jpg,.jpeg,.png':'.pdf,.docx,.txt,.jpg,.jpeg,.png'}" ${audio&&!x.storage_path?'required':''}><p class="muted">${audio?copyRaw("admin.097196389194"):watermarked?copyRaw("admin.ff5a50eb4564"):copyRaw("admin.7857b385ef4e")} ${copyHTML("admin.2f2c44eb1498")}${x.file_name?` Current file: ${e(x.file_name)}.`:''}</p>${x.storage_path&&!audio?`<label class="task"><input type="checkbox" name="detach"><span>${copyHTML("admin.7036a4e5cdbb")}</span></label>`:''}`;}if(['materials','lectureNotes'].includes(type))html+=watermarkEditor();if(type==='quizSets')html+=field('time_minutes',copyRaw("admin.0f8f608aa012"),x.time_minutes||10,'input','type="number" min="1" max="180" required')+field('difficulty',copyRaw("admin.be44133ed57f"),x.difficulty||'Practice');ui.modal(`${id?copyRaw("admin.464c4ffd019e"):copyRaw("admin.9fd728c66c9a")} ${types[type].toLowerCase()}`,`<form id="admin-form">${html}<p class="muted" id="admin-form-status" aria-live="polite"></p><div class="actions"><button class="btn primary" id="admin-save">${id?copyRaw("admin.dd0ae7a5cbcf"):copyRaw("admin.5f72328b3f6c")}</button><button type="button" class="btn" id="admin-cancel">${copyHTML("admin.19766ed6ccb2")}</button></div></form>`);if(['materials','lectureNotes'].includes(type))bindWatermarkEditor(document.querySelector('#admin-form'));document.querySelector('#admin-cancel').onclick=()=>{if(!busy)document.querySelector('#dialog').close();};document.querySelector('#admin-form').onsubmit=async ev=>{ev.preventDefault();if(busy)return;busy=true;const submit=document.querySelector('#admin-save'),status=document.querySelector('#admin-form-status');submit.disabled=true;let upload;let saved=false;try{const form=new FormData(ev.target),payload=Object.fromEntries(form);delete payload.upload;const watermarkOptions=['materials','lectureNotes'].includes(type)?readWatermark(ev.target):{};for(const key of Object.keys(payload))if(key.startsWith('watermark_'))delete payload[key];const controls=ev.target.querySelector('.watermark-editor');if(controls)controls.disabled=true;if(payload.detach){payload.storage_path=null;payload.file_name=null;payload.file_size=null;payload.mime_type=null;}delete payload.detach;if(payload.url){const u=new URL(payload.url);if(!['http:','https:'].includes(u.protocol))throw new Error(copyRaw("admin.8414a5b47093"));}if(type==='quizQuestions'){payload.options=[0,1,2,3].map(i=>payload[`option${i}`]);[0,1,2,3].forEach(i=>delete payload[`option${i}`]);payload.correct_index=Number(payload.correct_index);}if(type==='quizSets')payload.time_minutes=Number(payload.time_minutes);const file=form.get('upload');if(file?.size){status.textContent=copyRaw("admin.7cdfb59cd1d3");upload=await backend.upload(file,{audioOnly:type==='lectures',watermark:['materials','lectureNotes'].includes(type),watermarkOptions,onProgress:message=>{status.textContent=message;}});Object.assign(payload,upload);}if(type==='lectures'){payload.url='';if(!upload&&(!x.storage_path||x.storage_bucket!=='lexamah-audio'||!String(x.mime_type||'').startsWith('audio/')))throw new Error(copyRaw("admin.bdd41d220eef"));}status.textContent=copyRaw("admin.432798827065");await backend.cloudSave(type,payload,id);saved=true;document.querySelector('#dialog').close();await ui.reload();await loadAdmin();ui.toast(copyRaw("admin.7342bfed8e1e"));}catch(err){if(upload&&!saved){try{await backend.deleteFile(upload.storage_path,upload.storage_bucket);}catch{ui.toast(copyRaw("admin.d9257b44c065"));}}status.textContent=err.message;}finally{busy=false;submit.disabled=false;const controls=ev.target.querySelector('.watermark-editor');if(controls)controls.disabled=false;}};}
async function remove(id){const type=state.type,item=state.items[type].find(x=>x.id===id);if(!item)return;ui.modal(copyRaw("admin.060c4eb3793f"),`<p class="muted">${copyHTML("admin.5b7e3a54b292")}${e(item.title||item.name||item.front||item.question)}${copyHTML("admin.4a8e10073985")}${type==='quizSets'?' Its questions will also be removed. Sets with saved student attempts cannot be deleted.':''}</p>${item.storage_path?`<label class="task"><input id="admin-delete-file" type="checkbox"><span>${copyHTML("admin.2c418fad2666")}</span></label>`:''}<p class="muted" id="admin-delete-status" aria-live="polite"></p><div class="actions"><button class="btn danger" id="admin-confirm-delete">${copyHTML("admin.f256539ae020")}</button><button class="btn" id="admin-cancel-delete">${copyHTML("admin.4f655ad4f081")}</button></div>`);document.querySelector('#admin-cancel-delete').onclick=()=>document.querySelector('#dialog').close();document.querySelector('#admin-confirm-delete').onclick=async ev=>{ev.target.disabled=true;try{const deleteFile=document.querySelector('#admin-delete-file')?.checked;await backend.cloudDelete(type,id);let message='Resource deleted.';if(deleteFile){try{await backend.deleteFile(item.storage_path,item.storage_bucket||'lexamah-files');}catch{message='Resource deleted; its file remains in Storage. Remove it there if needed.';}}document.querySelector('#dialog').close();await ui.reload();await loadAdmin();ui.toast(message);}catch(err){document.querySelector('#admin-delete-status').textContent=err.message;ev.target.disabled=false;}};}
export function bindAdmin(){if(state.status!=='ready')return;if(state.type==='siteEditor'){bindSiteEditor(ui);return;}if(state.type==='samples'){bindSamples(ui);return;}if(state.type==='branding'){bindBranding(ui);return;}if(state.type==='downloadSettings'){bindDownloadSettings(ui);return;}if(['users','mail'].includes(state.type)){bindUsers(ui);return;}if(state.type==='about'){bindAboutEditor(ui);return;}if(state.type==='subjects'){bindSubjects(ui);return;}const search=document.querySelector('#admin-search');if(search)search.oninput=ev=>{state.query=ev.target.value;const pos=ev.target.selectionStart;ui.render();const next=document.querySelector('#admin-search');next.focus();next.setSelectionRange(pos,pos);};}
export async function adminClick(button){if(state.status==='ready'&&await usersClick(button,ui))return true;if(button.dataset.removeSubject){removeSubject(button.dataset.removeSubject,ui);return true;}if(button.id==='admin-refresh'){await loadAdmin();return true;}if(button.dataset.adminType){clearBrandingPreview();state.type=button.dataset.adminType;state.query='';ui.render();if(state.status==='ready')await loadUsersTab(state.type,ui);if(state.type==='downloadSettings')await loadDownloadSettings(ui);if(state.type==='samples')await loadSamples(ui);return true;}if(button.id==='admin-create'){edit();return true;}if(button.dataset.adminEdit){edit(button.dataset.adminEdit);return true;}if(button.dataset.adminDelete){await remove(button.dataset.adminDelete);return true;}return false;}
